INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (101, 'Nike Air Zoom Pegasus 41', 'nike-air-zoom-pegasus-41', 'Running', 'Chiến mã chạy bộ hàng ngày thế hệ mới với bộ đôi túi khí Air Zoom trước sau kết hợp bọt đệm ReactX hoàn toàn mới, tăng 13% độ hoàn trả năng lượng so với thế hệ trước. Phom ôm chân, phù hợp cự ly 5km - 21km.', 3490000, 3890000, 28, '["39","40","41","42","43","44"]', '["Trắng Phối Cam Volt","Đen Bạc"]', 'products/cec35df5-7c36-47b6-8e5b-fb3ee76b5f7e.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (102, 'Nike ZoomX Vaporfly 3', 'nike-zoomx-vaporfly-3', 'Running', 'Siêu giày đua marathon đỉnh cao thế giới. Tấm đĩa sợi carbon Flyplate nguyên khối đặt giữa hai lớp bọt siêu nhẹ ZoomX, mang lại lực đẩy về phía trước tối đa để bứt phá kỷ lục cá nhân (PR).', 5890000, 6490000, 14, '["40","41","42","43","44"]', '["Hồng Neon Bạc","Trắng Ngọc"]', 'products/5591edd2-a49c-4fb2-a408-7bbc1352d5ef.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (103, 'Nike Invincible 3', 'nike-invincible-3', 'Running', 'Vua đệm êm giảm chấn bảo vệ khớp gối. Khối lượng bọt ZoomX cực dày được đặt trên đế bè rộng giúp duy trì sự thăng bằng tối ưu, lý tưởng cho những ngày chạy phục hồi đường dài.', 4290000, 4790000, 20, '["40","41","42","43","44","45"]', '["Đen Trắng Phối Đỏ","Xám Bạc"]', 'products/813a5859-4714-49b9-a390-e2f9c8e82711.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (104, 'Nike Air Zoom Vomero 17', 'nike-air-zoom-vomero-17', 'Running', 'Sự kết hợp hoàn hảo giữa độ êm ái của bọt ZoomX bên trên và bọt Cushlon 3.0 bền bỉ bên dưới. Êm ái vượt trội, lưỡi gà và cổ giày đệm mút sang trọng.', 3890000, 4390000, 18, '["39","40","41","42","43"]', '["Xanh Navy Bạc","Trắng Platinum"]', 'products/3d8f58b3-c818-4eb3-98ac-002e3bf6f2d5.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (105, 'Nike Dunk Low Retro Panda', 'nike-dunk-low-retro-panda', 'Lifestyle', 'Biểu tượng phong cách đường phố toàn cầu. Phối màu Trắng Đen (Panda) kinh điển phối cùng chất da trơn dẻo dai, dễ dàng mix đồ từ quần jeans, ống thụng đến short thể thao.', 3190000, 3590000, 34, '["38","39","40","41","42","43","44"]', '["Trắng Đen (Panda)"]', 'products/fbeb9f29-0e7f-4856-b039-5cd2f24e8fa6.png', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (106, 'Nike Air Force 1 07 Triple White', 'nike-air-force-1-07-white', 'Lifestyle', 'Đôi sneaker trắng huyền thoại bất tử của Nike từ năm 1982. Đệm khí Nike Air ẩn trong gót, thân giày da thật viền may tinh xảo, tab kim loại AF-1 trên dây buộc sáng bóng.', 2890000, 3290000, 30, '["38","39","40","41","42","43","44"]', '["All White (Trắng Tinh Khôi)"]', 'products/cffb26e3-419f-4437-a770-87e445763db9.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (107, 'Nike Pegasus Trail 4 GORE-TEX', 'nike-pegasus-trail-4-gtx', 'Outdoor', 'Giày chạy địa hình dã ngoại chống nước tuyệt đối với màng GORE-TEX cao cấp. Đệm bọt React êm ái linh hoạt khi chuyển đổi từ đường nhựa thành phố sang đường mòn lầy lội.', 3990000, 4490000, 16, '["40","41","42","43","44"]', '["Xám Than Cam Rực","Đen Tuyển"]', 'products/25631a60-4b33-417c-aeaa-39715a4d1af4.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (108, 'Adidas Samba OG Classic', 'adidas-samba-og-classic', 'Lifestyle', 'Biểu tượng văn hóa thời trang bóng đá Terrace retro từ Đức. Thân da mềm cao cấp phối mũi da lộn chữ T kinh điển, đế cao su gum tự nhiên bám đường và mang phong cách trường tồn.', 2790000, 3190000, 31, '["39","40","41","42","43"]', '["Trắng Sọc Đen Mũi Xám","Đen Sọc Trắng"]', 'products/b8054072-8796-4b6c-89fb-fd993c1ec572.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (109, 'Adidas Gazelle Indoor', 'adidas-gazelle-indoor', 'Lifestyle', 'Bản nâng cấp đình đám với đế cao su gum trong suốt bao bọc quanh thân giày. Chất liệu da lộn mềm mịn thượng hạng với các tông màu vintage cuốn hút mọi ánh nhìn.', 2990000, 3390000, 22, '["38","39","40","41","42","43"]', '["Xanh Lá Đậm Sọc Trắng","Xanh Biển Nhạt"]', 'products/bb9efafd-b230-46f8-84d5-7351116a15b7.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (110, 'Adidas Superstar 82 Originals', 'adidas-superstar-82-originals', 'Lifestyle', 'Huyền thoại mũi sò Shell-toe xuất hiện trên mọi sàn diễn hip-hop và bóng rổ từ 1969. Chất da hạt dày dặn, viền 3 sọc răng cưa đục lỗ thông khí thoáng mát.', 2590000, 2990000, 25, '["39","40","41","42","43","44"]', '["Trắng Sọc Đen Gót Đen"]', 'products/46ea86a6-a567-4d45-8c3d-0f7ac77b3258.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (111, 'Adidas Ultraboost Light', 'adidas-ultraboost-light', 'Running', 'Thế hệ đệm bọt Light BOOST nhẹ hơn 30% so với Boost truyền thống, mang lại bước chạy siêu êm ái, bồng bềnh và trả lực liên tục. Thân dệt Primeknit ôm khít như đôi tất.', 4190000, 4890000, 20, '["40","41","42","43","44","45"]', '["Trắng Phối Đỏ Cam","Đen Core Black"]', 'products/2f7edccb-7212-49e7-9f7f-24576c9b0832.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (112, 'Adidas Adizero Adios Pro 3', 'adidas-adizero-adios-pro-3', 'Running', 'Vũ khí vô địch các giải World Marathon Majors. Trang bị hệ thống thanh năng lượng sợi carbon ENERGYRODS 2.0 mô phỏng cấu trúc xương ngón chân cùng 2 tầng bọt Lightstrike Pro siêu nảy.', 5990000, 6590000, 12, '["40","41","42","43","44"]', '["Xanh Ngọc Solar Red","Trắng Bạc"]', 'products/7d7081d8-c9b2-468f-8287-605dfdb78705.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (113, 'Adidas Adizero Boston 12', 'adidas-adizero-boston-12', 'Running', 'Mẫu giày luyện tập tốc độ (tempo / interval) và cự ly dài ưa chuộng nhất. Đệm kép kết hợp Lightstrike Pro êm nảy và Lightstrike 2.0 bền chắc cùng thanh carbon Energyrods trợ lực.', 3790000, 4290000, 19, '["39","40","41","42","43"]', '["Trắng Sọc Đen Neon","Xanh Dương Đậm"]', 'products/cdb8fe90-b63e-4add-87fb-6641c3ccd407.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (114, 'Adidas Terrex Free Hiker 2 GORE-TEX', 'adidas-terrex-free-hiker-2-gtx', 'Outdoor', 'Giày dã ngoại trekking leo núi đỉnh cao với đế đệm Boost êm ái trên từng mỏm đá gồ ghề. Đế ngoài cao su Continental siêu bám địa hình trơn ướt cùng màng GORE-TEX chống nước hoàn toàn.', 4490000, 5190000, 15, '["40","41","42","43","44"]', '["Xám Bạc Đen Vàng Rừng","Xanh Rêu Đen"]', 'products/8c8bf4ba-1a1c-4c88-afc3-2b8d01b11a5a.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (115, 'New Balance 550 White Grey', 'new-balance-550-white-grey', 'Lifestyle', 'Tái hiện mẫu giày bóng rổ cổ thấp vintage năm 1989. Thiết kế dad shoes thanh lịch, chất da phối viền xám nhẹ nhàng, logo N dập nổi đặc trưng dễ dàng mix đồ thanh lịch.', 2990000, 3490000, 26, '["39","40","41","42","43","44"]', '["Trắng Xám Bạc","Trắng Xanh Navy"]', 'products/db605f4c-72e6-4a5f-a3ca-efb746bb5be6.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (116, 'New Balance 530 Steel Grey', 'new-balance-530-steel-grey', 'Lifestyle', 'Cơn sốt giày retro runner đầu những năm 2000. Thân giày bằng lưới mắt to siêu thoáng khí kết hợp các dải da bóng sắc nét, đế đệm ABZORB hấp thụ chấn động mềm mại khi di chuyển.', 2690000, 3090000, 30, '["38","39","40","41","42","43"]', '["Xám Bạc Ánh Kim","Trắng Phối Xanh Dương"]', 'products/92f37ba8-9095-44b9-99d9-7129e94221ff.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (117, 'New Balance 2002R Protection Pack', 'new-balance-2002r-protection-pack', 'Lifestyle', 'Thiết kế viền da lộn rách xước có chủ đích (deconstructed) độc nhất vô nhị. Trang bị công nghệ đế đệm N-ergy cao cấp và ABZORB SBS giảm sốc vượt trội dưới gót chân.', 3990000, 4590000, 18, '["40","41","42","43","44"]', '["Xám Khói Rain Cloud","Đen Phantom"]', 'products/a1b370be-d06e-444c-8ba2-40e5a96c9861.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (118, 'New Balance 1906R Metallic Silver', 'new-balance-1906r-metallic-silver', 'Lifestyle', 'Mẫu giày Tech-runner mang hơi thở tương lai. Khung nhựa gót TPU Stability Web hỗ trợ vòm bàn chân, hệ thống dây khóa N-Lock giữ mu bàn chân ổn định trên từng sải bước.', 3890000, 4390000, 17, '["39","40","41","42","43"]', '["Bạc Metallic Ánh Vàng","Trắng Phối Xanh Lá"]', 'products/45f8f7e8-20eb-46be-9b2d-44d761f97a23.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (119, 'New Balance Fresh Foam X 1080v13', 'new-balance-fresh-foam-x-1080v13', 'Running', 'Đỉnh cao êm ái của New Balance với khối bọt Fresh Foam X thế hệ mới nhất, mang lại cảm giác tiếp đất mềm như kẹo dẻo và chuyển động lăn bàn chân siêu mượt mà.', 4390000, 4890000, 20, '["40","41","42","43","44","45"]', '["Xanh Biển Phối Trắng","Đen Bạc"]', 'products/77b2e56f-1249-486e-a30c-8d01292c5a7d.webp', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (120, 'New Balance FuelCell Rebel v4', 'new-balance-fuelcell-rebel-v4', 'Running', 'Giày chạy tốc độ không cần đĩa carbon nhẹ nhất phân khúc với bọt đệm FuelCell pha PEBA siêu nảy. Thiết kế mũi bè chuẩn phom bàn chân người Châu Á, bứt tốc độ cực nhạy.', 3590000, 3990000, 16, '["39","40","41","42","43","44"]', '["Trắng Phối Đỏ Neon","Xanh Da Trời"]', 'products/b1026aec-1f9c-4b35-8201-c992dc2b03bf.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (121, 'New Balance Fresh Foam X Hierro v8', 'new-balance-fresh-foam-x-hierro-v8', 'Outdoor', 'Chiến binh việt dã địa hình với đế ngoài cao su Vibram Megagrip bám dính chắc chắn trên mọi cung đường bùn đất, đá dăm kết hợp đệm Fresh Foam X bảo vệ khớp chân.', 3790000, 4290000, 15, '["40","41","42","43","44"]', '["Xám Đất Nung Phối Đen","Xanh Rêu"]', 'products/6d93f495-76c5-45de-ba57-96bcdf091c56.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (122, 'Puma Palermo Leather Gum', 'puma-palermo-leather-gum', 'Lifestyle', 'Hồi sinh phong cách bóng đá Terrace thập niên 80 từ bờ biển nước Ý. Chất da tự nhiên mềm mại phối mũi da lộn, đế gum retro và tag da vàng kim chữ Palermo sang trọng.', 2490000, 2890000, 24, '["39","40","41","42","43"]', '["Xanh Cốm Trắng","Hồng Pastel Phối Trắng"]', 'products/f925b801-9d28-4666-a646-d9f8dd6ddc4e.png', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (123, 'Puma Suede Classic XXI', 'puma-suede-classic-xxi', 'Lifestyle', 'Đôi giày da lộn bất tử của văn hóa đường phố và b-boy breakdance từ năm 1968. Da lộn nhung cao cấp dày dặn, dải Formstrip uốn lượn bên sườn tạo dấu ấn nhận diện không thể nhầm lẫn.', 1990000, 2390000, 28, '["38","39","40","41","42","43","44"]', '["Đen Sọc Trắng","Đỏ Sọc Trắng"]', 'products/83d25424-0117-437e-bde7-c1a7f20d270d.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (124, 'Puma Army Trainer Retro', 'puma-army-trainer-retro', 'Lifestyle', 'Thiết kế nguyên bản của dòng giày huấn luyện quân đội Đức (German Army Trainer). Tối giản, thanh lịch với da trơn trắng và mũi da lộn chữ T xám, đế bệt bền bỉ.', 2290000, 2690000, 20, '["39","40","41","42","43"]', '["Trắng Xám Đế Gum"]', 'products/7ae1fd2b-4bb8-47de-ac5d-b99f234bd1c9.webp', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (125, 'Puma Deviate Nitro 2 Carbon', 'puma-deviate-nitro-2-carbon', 'Running', 'Giày chạy bộ trợ lực đĩa carbon composite INNOPLATE cao cấp kết hợp lớp bọt bơm khí nitơ Nitro Elite siêu nhẹ và nảy. Độ bám đường đỉnh cao với đế cao su PUMAGRIP bám cả trên mặt đường ướt.', 3990000, 4590000, 16, '["40","41","42","43","44"]', '["Cam Neon Phối Đen","Trắng Bạc"]', 'products/7e992928-568f-435a-9545-2260c5dc9fe9.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (126, 'Puma Velocity Nitro 3', 'puma-velocity-nitro-3', 'Running', 'Được đánh giá là đôi giày chạy bộ hàng ngày đáng tiền nhất. Đệm bọt NITRO êm ái, nhẹ và êm, độ bền vượt 1000km, phù hợp cho cả người mới chạy và vận động viên cự ly dài.', 2990000, 3490000, 22, '["39","40","41","42","43","44"]', '["Xanh Dương Điện Tử","Đen Phối Vàng Chanh"]', 'products/4fe231a4-3891-429e-93d7-181d8d37e5b6.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (127, 'Puma MB.03 Toxic LaMelo Ball', 'puma-mb03-toxic-lamelo-ball', 'Basketball', 'Giày bóng rổ signature phá cách của ngôi sao NBA LaMelo Ball. Đồ họa vết cào xé độc đáo, đệm bọt NITRO bùng nổ sức bật và đế ngoài cao su siêu bám sân sàn gỗ hoặc bê tông.', 3390000, 3890000, 15, '["40","41","42","43","44","45"]', '["Tím Neon Độc Lạ","Trắng Đen"]', 'products/2a0b12fe-97bf-4c24-b414-be2480a348d4.webp', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (128, 'Puma Voyage Nitro 3 Trail', 'puma-voyage-nitro-3-trail', 'Outdoor', 'Giày dã ngoại địa hình bám chắc mọi bề mặt sỏi đá với hợp chất cao su PUMAGRIP-ATR đa hướng. Hệ thống dây buộc OPTIFIT ôm chắc mu bàn chân khi đổ dốc an toàn.', 3290000, 3790000, 14, '["40","41","42","43","44"]', '["Đen Phối Xanh Olive","Xám Bạc"]', 'products/6a6d228d-cdac-405a-a292-b40094a9a544.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (129, 'Salomon XT-6 Black Phantom', 'salomon-xt-6-black-phantom', 'Outdoor', 'Ngôi sao dẫn đầu trào lưu thời trang Gorpcore toàn cầu từ dãy núi Alps nước Pháp. Khung đế Agile Chassis System (ACS) chống vặn xoắn gót chân, màng ép nhiệt TPU bền bỉ và dây rút Quicklace tiện lợi.', 4690000, 5290000, 20, '["40","41","42","43","44"]', '["Đen Toàn Diện (Black Phantom)","Trắng Be Bạc"]', 'products/aa1a37e2-52d9-40f2-ba48-9bd4d5386729.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (130, 'Salomon ACS Pro Advanced Metal', 'salomon-acs-pro-advanced-metal', 'Outdoor', 'Thiết kế Techwear tương lai mang tính kỹ thuật cao với hệ thống lồng thông gió Kurim hai bên hông giày. Khung đỡ Kurim giữ vững bàn chân khi di chuyển ở mọi địa hình gồ ghề.', 4990000, 5590000, 15, '["40","41","42","43","44"]', '["Kim Loại Bạc Trắng","Đen Tuyển"]', 'products/b47c2216-8e7e-4347-9f72-831c1338c32e.webp', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (131, 'Salomon Speedcross 6 Grip', 'salomon-speedcross-6-grip', 'Outdoor', 'Vua bám bùn đất của làng chạy việt dã. Gai đế Chevron hình chữ V sắc nhọn găm sâu vào đất mềm và bùn lầy, thân giày kháng xé sợi ripstop và bảo vệ ngón chân chống va đập.', 3690000, 4190000, 18, '["39","40","41","42","43"]', '["Đen Đỏ Rực","Xanh Biển Phối Đen"]', 'products/4ce8ed16-8e81-440f-bcb9-c3a8779b03ae.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (132, 'Salomon Pulsar Trail Pro', 'salomon-pulsar-trail-pro', 'Outdoor', 'Giày việt dã tốc độ trang bị đĩa Energy Blade bằng sợi tổng hợp đẩy người chạy lao về phía trước, bọt Energy Foam siêu nảy giúp giữ sức trên các cự ly chạy trail 50km - 100km.', 3890000, 4390000, 14, '["40","41","42","43","44"]', '["Đỏ Cam Hoàng Hôn","Trắng Bạc"]', 'products/c88b7129-f095-4896-82a0-9ae4ad9fae1a.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (133, 'Salomon XT-4 OG Fiery Red', 'salomon-xt-4-og-fiery-red', 'Outdoor', 'Bản phối màu gradient rực lửa nguyên bản từ lịch sử đường mòn Salomon. Khung đế nâng đỡ toàn phần bền bỉ như áo giáp, đế Contagrip kiểm soát trơn trượt trên đá ướt.', 4590000, 5190000, 16, '["40","41","42","43","44"]', '["Đỏ Rực Phối Vàng Cam","Trắng Đen"]', 'products/753ab55c-f647-4960-a21d-586c1ec2ebc0.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (134, 'Salomon X Ultra 4 GORE-TEX', 'salomon-x-ultra-4-gtx', 'Outdoor', 'Đôi giày trekking dã ngoại bán chạy nhất của Salomon. Công nghệ ADV-C Chassis khóa chặt khớp mắt cá ngoài, bảo vệ bàn chân không bị lật khi bước qua đá gồ ghề nguy hiểm.', 3790000, 4290000, 19, '["40","41","42","43","44"]', '["Đen Xám Bạc","Xanh Rêu Xám"]', 'products/d78a487b-e35f-4e1a-92ca-15ee1a52f2be.png', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (135, 'Salomon Speedverse PRG', 'salomon-speedverse-prg', 'Lifestyle', 'Sự giao thoa táo bạo giữa giày địa hình và thời trang dạo phố đương đại. Các đường vân uốn lượn sắc bén trên thân giày phối da và lưới dệt 3D cao cấp.', 3990000, 4490000, 15, '["39","40","41","42","43"]', '["Trắng Ngà Phối Xám","Đen Tuyền"]', 'products/02f888fe-ae3b-4160-ad49-9ce12c60fe02.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (136, 'Asics Gel-Nimbus 26 PureGEL', 'asics-gel-nimbus-26-puregel', 'Running', 'Được mệnh danh là đôi giày chạy êm nhất thế giới của Nhật Bản. Công nghệ PureGEL giấu bên trong gót mềm hơn 65% so với gel truyền thống kết hợp bọt FF BLAST+ ECO bảo vệ đầu gối tuyệt đối.', 4190000, 4690000, 25, '["40","41","42","43","44","45"]', '["Xanh Biển Phối Trắng","Đen Platinum"]', 'products/e54f1a0b-4b3d-4197-9a6a-d1e3a631e9a0.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (137, 'Asics Gel-Kayano 31 4D Guidance', 'asics-gel-kayano-31-4d-guidance', 'Running', 'Vua của dòng giày ổn định và chống sụp vòm chân. Hệ thống 4D GUIDANCE SYSTEM tự động điều chỉnh thích ứng theo từng chuyển động mỏi của bàn chân, giữ thăng bằng hoàn hảo.', 4390000, 4990000, 22, '["40","41","42","43","44","45"]', '["Xám Bạc Băng Giá","Đen Phối Vàng Đồng"]', 'products/d7cd9b39-506b-4646-a844-e69e207e775e.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (138, 'Asics Novablast 4 Trampoline', 'asics-novablast-4-trampoline', 'Running', 'Thiết kế đế hình học bạt nhún trampoline độc quyền mang lại cảm giác nảy bật tưng bừng trên từng bước chạy. Trọng lượng siêu nhẹ với bọt đệm FF BLAST+ ECO tái tạo năng lượng dồi dào.', 3690000, 4190000, 28, '["39","40","41","42","43","44"]', '["Trắng Phối Xanh Neon","Đen Xám Khói"]', 'products/451302df-a923-42a8-a1d2-4c5b371b8537.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (139, 'Asics GT-2000 12 Stability', 'asics-gt-2000-12-stability', 'Running', 'Sự cân bằng hoàn hảo giữa độ nhẹ linh hoạt và khả năng trợ lực cổ chân với công nghệ 3D GUIDANCE SYSTEM, bền bỉ và cực kỳ đáng tin cậy cho những buổi chạy hằng ngày.', 3390000, 3890000, 18, '["40","41","42","43","44"]', '["Xanh Navy Trắng","Xám Đen"]', 'products/38398a69-a749-4426-ba28-b78c33df0b3d.webp', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (140, 'Asics Gel-NYC Cream Oyster Grey', 'asics-gel-nyc-cream-oyster-grey', 'Lifestyle', 'Hòa quyện di sản thiết kế cổ điển GEL-NIMBUS 3 và GEL-CUMULUS 16 thành tuyệt tác thời trang retro runner đương đại. Đệm GEL lộ ra ở cả gót và mũi tạo nét cá tính khác biệt.', 3490000, 3990000, 20, '["39","40","41","42","43","44"]', '["Kem Xám Bạc (Cream Oyster)","Trắng Phối Xanh Rêu"]', 'products/6c3f6211-a6e3-4c7f-8ba5-621d7cefced5.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (141, 'Asics Metaspeed Sky Paris Carbon', 'asics-metaspeed-sky-paris-carbon', 'Running', 'Siêu phẩm giày đua marathon kỷ lục tại Thế vận hội Paris. Bọt FF TURBO PLUS siêu nẩy kết hợp đĩa carbon mở rộng giúp các chân chạy sải bước dài hơn mà tốn ít sức lực nhất.', 6290000, 6990000, 9, '["40","41","42","43","44"]', '["Đỏ Cam Lửa Paris","Trắng Bạc"]', 'products/4ca4e07a-5f0b-4d04-b9f6-916338121ca1.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (142, 'Asics Gel-Trabuco 12 Trail', 'asics-gel-trabuco-12-trail', 'Outdoor', 'Đôi giày việt dã bảo vệ bàn chân toàn diện trên cung đường đá dăm với tấm chống đá nhọn (Rock Protection Plate) và cao su ASICSGRIP bám dính siêu hạng trên đá ướt.', 3590000, 4090000, 15, '["40","41","42","43","44"]', '["Xanh Đen Cam","Xám Rừng"]', 'products/aedb1829-696e-4adf-b246-b0867c457ad5.webp', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (143, 'Onitsuka Tiger Mexico 66 White Blue Red', 'onitsuka-tiger-mexico-66-white-blue-red', 'Lifestyle', 'Huyền thoại sọc hổ bất tử từ Thế vận hội Mexico 1968. Thân giày bằng da bò mềm mại ôm gọn bàn chân thanh mảnh, lưỡi gà chéo sau gót kinh điển mang phong cách hoài cổ xứ Phù Tang.', 2890000, 3390000, 30, '["38","39","40","41","42","43"]', '["Trắng Sọc Xanh Đỏ","Trắng Sọc Đen"]', 'products/7f786a7d-1f48-4c7d-91b9-55e397ef5e6a.png', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (144, 'Onitsuka Tiger Mexico 66 SD Leather', 'onitsuka-tiger-mexico-66-sd-leather', 'Lifestyle', 'Phiên bản kỷ niệm Super Deluxe (SD) chế tác từ da thuộc thượng hạng Nhật Bản. Bổ sung đệm bọt amplifoam ở gót chân giúp êm ái hơn hẳn phiên bản truyền thống.', 3790000, 4290000, 18, '["39","40","41","42","43"]', '["Trắng Ngà Da Mềm","Đen Sọc Bạc"]', 'products/72c2389f-1fec-41ff-91bf-0c6fdd8a4a7c.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (145, 'Onitsuka Tiger Serrano Retro Gold', 'onitsuka-tiger-serrano-retro-gold', 'Lifestyle', 'Lấy cảm hứng từ giày đinh điền kinh thập niên 70 với dáng mũi giày cong nhẹ thanh thoát. Thân vải dù siêu nhẹ phối da lộn hai bên mang lại cảm giác nhẹ bẫng khi di chuyển.', 2390000, 2790000, 22, '["38","39","40","41","42","43"]', '["Vàng Ánh Kim Sọc Xanh","Xanh Navy Sọc Trắng"]', 'products/9615aa63-0a67-485d-b022-6e354e59193f.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (146, 'Onitsuka Tiger Tokuten Indoor Gum', 'onitsuka-tiger-tokuten-indoor-gum', 'Lifestyle', 'Phong cách giày sân bóng trong nhà cổ điển với chất da lộn mịn bao bọc mũi giày và đế cao su gum tự nhiên dày dặn, đang là một trong những mẫu giày hot trend được giới trẻ săn đón.', 2690000, 3090000, 24, '["39","40","41","42","43"]', '["Trắng Sọc Đen Đế Gum","Xám Bạc"]', 'products/f51a9293-252e-410b-a4f2-6d011c79c554.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (147, 'Onitsuka Tiger GSM Court Vintage', 'onitsuka-tiger-gsm-court-vintage', 'Lifestyle', 'Viết tắt của Game - Set - Match, mẫu giày tennis cổ điển thập niên 80. Các đường dập lỗ ziczac trên thân da trơn thanh lịch, đế phẳng nâng niu bàn chân suốt cả ngày dài.', 2590000, 2990000, 20, '["39","40","41","42","43","44"]', '["Trắng Sọc Xanh Hunter","Trắng Sọc Đỏ Rượu"]', 'products/7d93aeea-b713-4251-bebc-de660757d5db.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (148, 'Onitsuka Tiger Delegation EX Chunky', 'onitsuka-tiger-delegation-ex-chunky', 'Lifestyle', 'Bản phối hiện đại đế dày chunky thời thượng cải tiến từ giày của đoàn thể thao Nhật Bản năm 1964. Tích hợp bọt đệm FLYTEFOAM PROPEL siêu êm ái tăng chiều cao tinh tế.', 3490000, 3990000, 16, '["38","39","40","41","42","43"]', '["Trắng Phối Đỏ Xanh","Đen Nguyên Bản"]', 'products/a3cda5f1-81b5-4ae2-818f-8a59a7d36872.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (149, 'Onitsuka Tiger Mexico 66 Yellow Kill Bill', 'onitsuka-tiger-mexico-66-yellow-kill-bill', 'Lifestyle', 'Phối màu vàng sọc đen biểu tượng gắn liền với Lý Tiểu Long và bộ phim Kill Bill huyền thoại. Điểm nhấn nổi bật độc nhất vô nhị làm bừng sáng mọi bộ trang phục dạo phố.', 2990000, 3490000, 26, '["38","39","40","41","42","43"]', '["Vàng Sọc Đen (Kill Bill)"]', 'products/4ae0b8b6-ab31-4b22-8100-97574df8ed6f.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (150, 'Mizuno Wave Rider 28 Enerzy', 'mizuno-wave-rider-28-enerzy', 'Running', 'Dòng giày chạy biểu tượng suốt gần 30 năm qua của Nhật Bản. Đĩa đệm cơ học Wave độc quyền phân tán lực chấn động kết hợp bọt MIZUNO ENERZY NXT đàn hồi siêu nảy và bền bỉ vượt trội.', 3590000, 4090000, 23, '["39","40","41","42","43","44"]', '["Xanh Dương Bạc","Trắng Xám"]', 'products/d6d7dd0a-91b7-412f-8568-f85b38332912.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (151, 'Mizuno Wave Inspire 20 Support', 'mizuno-wave-inspire-20-support', 'Running', 'Dành riêng cho những người có vòm chân bẹt và cổ chân dễ bị lật trong. Đĩa Wave bất đối xứng tăng cường độ cứng ở phía má trong giúp giữ thẳng trục mắt cá chân an toàn.', 3490000, 3990000, 18, '["40","41","42","43","44"]', '["Xanh Đen Phối Cam","Xám Platinum"]', 'products/17a9d1ed-c237-4819-90eb-1de4f9050834.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (152, 'Mizuno Wave Skyrise 5 Floating', 'mizuno-wave-skyrise-5-floating', 'Running', 'Cảm giác chạy bồng bềnh như lướt trên mây với công nghệ đệm kép MIZUNO ENERZY CORE siêu êm dưới lòng bàn chân. Dáng giày thanh thoát, vải lưới Jacquard thoáng khí tối đa.', 3290000, 3790000, 20, '["39","40","41","42","43","44"]', '["Trắng Xanh Bạc","Đen Khói"]', 'products/06af459a-f85a-4c94-ac05-c2d8729828f8.png', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (153, 'Mizuno Wave Rebellion Pro 2 Carbon', 'mizuno-wave-rebellion-pro-2-carbon', 'Running', 'Siêu giày đua marathon phá cách với thiết kế vát gót khí động học cực hạn. Đĩa đệm Carbon tăng cường sợi thủy tinh và bọt Enerzy Lite+ giúp guồng chân xoay nhanh kinh ngạc.', 5590000, 6290000, 11, '["40","41","42","43","44"]', '["Vàng Chanh Phối Tím Neon"]', 'products/0924d363-f51b-47ae-b1a4-7ceb4d2cd068.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (154, 'Mizuno Wave Mujin 10 Michelin Trail', 'mizuno-wave-mujin-10-michelin-trail', 'Outdoor', 'Hợp tác đỉnh cao với hãng lốp xe số 1 thế giới Michelin. Hợp chất cao su lốp Michelin bám dính siêu hạng trên bùn ướt và đá trơn trượt cùng đĩa đệm Wave ổn định địa hình hiểm trở.', 3790000, 4290000, 15, '["40","41","42","43","44"]', '["Xanh Rừng Phối Đen","Xám Đất"]', 'products/d1a04fd0-a4e0-477e-9729-9c30f583a065.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (155, 'Mizuno Wave Momentum 3 Court', 'mizuno-wave-momentum-3-court', 'Basketball', 'Giày thi đấu thể thao trong nhà (Bóng chuyền, Bóng rổ, Cầu lông) với thiết kế cổ giày bootie ôm khít mắt cá, đĩa Wave trợ lực bật nhảy và đế không để lại vệt màu trên sàn (Non-marking).', 3390000, 3890000, 16, '["40","41","42","43","44"]', '["Trắng Xanh Neon","Đen Bạc"]', 'products/44edb7b9-2b7f-4da6-9fc0-4d1b60892267.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (156, 'Mizuno Contender Retro Sport', 'mizuno-contender-retro-sport', 'Lifestyle', 'Mẫu sneaker mang đậm tinh thần hoài cổ thập niên 90 với logo chim Runbird dũng mãnh dập nổi hai bên. Phom dáng đầm chắc, da lộn phối vải lưới cao cấp.', 2490000, 2890000, 20, '["39","40","41","42","43"]', '["Trắng Xám Runbird Đỏ","Xanh Navy Trắng"]', 'products/06c8241d-86ee-4a5d-8635-0f5e0cbe1a0a.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (157, 'Li-Ning Feidian 3.0 Elite Carbon', 'li-ning-feidian-3-elite-carbon', 'Running', 'Vũ khí marathon đỉnh cao càn quét các bục vinh quang. Đĩa đệm Carbon nguyên khối uốn cong toàn phần kết hợp bọt đệm BOOM (bọt béo PEBA ép nhiệt siêu tới hạn) đàn hồi hơn 80%.', 3990000, 4590000, 15, '["39","40","41","42","43","44"]', '["Trắng Phối Cam Cháy","Xanh Lam Neon"]', 'products/3be60ae9-4d0a-4fd1-8bc4-092a88962875.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (158, 'Li-Ning Yueying 3 Pro Dual BOOM', 'li-ning-yueying-3-pro-dual-boom', 'Running', 'Dòng giày chạy hàng ngày được ưa chuộng bậc nhất của Li-Ning với 2 tầng bọt BOOM êm ái bảo vệ cổ chân, khung TPU Probar Loc chống vặn xoắn giữa bàn chân vững chãi.', 2790000, 3190000, 22, '["39","40","41","42","43"]', '["Trắng Tím Hologram","Đen Bạc"]', 'products/a3669d83-a3c3-49da-9661-3f41a5757fbd.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (159, 'Li-Ning Super Light 21 Breeze', 'li-ning-super-light-21-breeze', 'Running', 'Dòng giày chạy siêu nhẹ kỷ lục chỉ khoảng 180g mỗi chiếc. Thân giày bằng sợi dệt trong suốt thoáng khí giải nhiệt mùa hè kết hợp đệm bọt BOOM êm nảy.', 2290000, 2690000, 25, '["38","39","40","41","42","43"]', '["Xanh Băng Tuyết","Hồng Cam Bình Minh"]', 'products/e67bdf89-9450-457c-8d9b-a121e0d29c3b.webp', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (160, 'Li-Ning Way of Wade 10 Mint Blossom', 'li-ning-way-of-wade-10-mint-blossom', 'Basketball', 'Siêu phẩm bóng rổ hợp tác cùng huyền thoại NBA Dwyane Wade. Tấm đĩa carbon kéo dài toàn bộ đế, lớp bọt BOOM toàn diện bọc trong khung TPU trong suốt, bám sàn gỗ đỉnh cao.', 4990000, 5690000, 14, '["40","41","42","43","44","45"]', '["Xanh Bạc Hà Mint Blossom","Đen Vàng Kim"]', 'products/0aafc4f0-3d06-46c8-95f2-1b95f85eba58.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (161, 'Li-Ning YuShuai 18 V2 Streetball', 'li-ning-yushuai-18-v2-streetball', 'Basketball', 'Dòng giày bóng rổ cày sân bê tông nức tiếng bền bỉ suốt 18 thế hệ. Đế cao su TUFF RB chống mài mòn gấp 5 lần cao su thông thường kết hợp đệm BOOM bảo vệ đầu gối khi va chạm.', 2890000, 3390000, 20, '["40","41","42","43","44"]', '["Trắng Đỏ Lửa","Đen Tuyền"]', 'products/66a3894b-c7fd-43e7-8085-c4c81509298b.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (162, 'Li-Ning Shadow 2 Double Carbon', 'li-ning-shadow-2-double-carbon', 'Running', 'Thiết kế rỗng ruột tương lai mang tính đột phá với 2 tấm đĩa carbon song song uốn cong tạo thành hệ thống đàn hồi cơ học Jiang Technology, trả lực mạnh mẽ chưa từng có.', 5290000, 5990000, 8, '["40","41","42","43","44"]', '["Trắng Đen Phối Đỏ Neon"]', 'products/e252858f-0660-42ed-aaf0-5376e7ee8b19.webp', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (163, 'Li-Ning Rouge Rabbit 7 Pro', 'li-ning-rouge-rabbit-7-pro', 'Running', 'Đôi giày chạy quốc dân thế hệ thứ 7 với bọt đệm BOOM nhẹ êm cùng đế ngoài GCR bám ướt cải tiến. Mức giá cực kỳ hợp lý cho người tập chạy bộ và rèn luyện thể thao hàng ngày.', 2190000, 2590000, 26, '["39","40","41","42","43"]', '["Trắng Phối Cam Đào","Xanh Biển Nhạt"]', 'products/851712fe-d7b8-4634-9c75-68bd95dafddb.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (164, 'Anta KT8 Shock The Game Klay Thompson', 'anta-kt8-shock-the-game-klay-thompson', 'Basketball', 'Dòng giày thi đấu đỉnh cao của nhà vô địch NBA Klay Thompson. Thiết kế cổ giày có thể gập xuống thành cổ thấp, đệm NitroEdge nảy cực nhạy kết hợp thanh xoắn 3D carbon nâng đỡ.', 2790000, 3290000, 15, '["40","41","42","43","44"]', '["Xanh Tím Neon Vịnh San Francisco","Trắng Vàng Warriors"]', 'products/bc29f057-14da-4d9b-86b2-cc83897c1981.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (165, 'Anta KT9 3D Carbon Stabilizer', 'anta-kt9-3d-carbon-stabilizer', 'Basketball', 'Thế hệ thứ 9 với hệ thống ổn định SMART S.A.M hấp thụ đến 95% lực phản hồi khi tiếp đất, khóa gót carbon đa hướng giúp các tay ném giữ thăng bằng tuyệt đối trên không trung.', 3290000, 3790000, 15, '["40","41","42","43","44","45"]', '["Đen Phantom Phối Vàng Kim","Trắng Băng"]', 'products/d8e62070-9407-4121-adc2-21a4e555421b.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (166, 'Anta Shock The Game 7 Cement King', 'anta-shock-the-game-7-cement-king', 'Basketball', 'Vua của các trận bóng rổ đường phố ngoại trời. Đế gai sâu cao su xi măng A-Hardcourt RB siêu chống mài mòn, bọc mũi TPU chống va đập ngón chân khi va chạm quyết liệt.', 2390000, 2790000, 22, '["40","41","42","43","44"]', '["Xám Bê Tông Phối Đỏ Lửa","Đen Tím"]', 'products/069e5a20-f30e-4290-84f5-f163971dff7f.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (167, 'Anta C202 GT Pro Carbon Racing', 'anta-c202-gt-pro-carbon-racing', 'Running', 'Siêu giày đua marathon đẳng cấp quốc tế của Anta với đĩa carbon 3D ôm trọn vòm chân cùng bọt Nitro siêu nảy đàn hồi đến 84%. Trọng lượng nhẹ chỉ 195g cho sải bước thần tốc.', 4190000, 4790000, 3, '["40","41","42","43","44"]', '["Cam Lửa Bạc","Trắng Xanh Biển"]', 'products/c4674665-d6d4-424c-8736-534930bb6832.jpg', 1, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (168, 'Anta PG7 Nitro Daily Cushion', 'anta-pg7-nitro-daily-cushion', 'Running', 'Đôi giày chạy bộ đệm êm thường ngày ứng dụng công nghệ đệm khí nitơ Nitro Tech thế hệ mới. Đem lại cảm giác mềm mại như giẫm trên thảm cỏ, phù hợp cho người mới bắt đầu.', 2190000, 2590000, 25, '["39","40","41","42","43","44"]', '["Trắng Xám Bạc","Xanh Dương Đậm"]', 'products/44d615fe-f763-4f31-9047-f8c6f0ecaf30.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (169, 'Anta Mach 4 Speed Training', 'anta-mach-4-speed-training', 'Running', 'Mẫu giày rèn luyện tốc độ (Tempo run) không đĩa carbon được các runner Châu Á đánh giá rất cao. Thân lưới dệt thoáng khí, đệm bọt nảy nhạy bén giúp guồng chân đều nhịp.', 2490000, 2890000, 20, '["39","40","41","42","43"]', '["Trắng Phối Xanh Neon","Đen Đỏ"]', 'products/bcbd3bc0-237d-41bc-a692-c440a4aaaec4.jpg', 0, '2026-11-01 01:00:05');
INSERT INTO products (id, name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured, created_at) VALUES (170, 'Anta Walker Retro Casual', 'anta-walker-retro-casual', 'Lifestyle', 'Giày dạo phố retro phong cách casual năng động với mức giá cực kỳ dễ tiếp cận. Thân da tổng hợp phối vải thoáng, đệm êm nâng đỡ bàn chân khi đi bộ nhiều giờ liền.', 1890000, 2290000, 28, '["39","40","41","42","43","44"]', '["Trắng Sọc Xanh Navy","Trắng Toàn Diện"]', 'products/e3696638-2585-4f74-a15c-b98c5eac3094.jpg', 0, '2026-11-01 01:00:05');
